method total_match(lst1: seq<string>, lst2: seq<string>) returns (result: seq<string>)
    requires |lst1| >= 0 && |lst2| >= 0 // Both lists can be empty
    ensures result == lst1 || result == lst2 // The result is either lst1 or lst2
    ensures (SumChars(lst1) < SumChars(lst2)) ==> (result == lst1) // If lst1 has fewer chars, return lst1
    ensures (SumChars(lst1) > SumChars(lst2)) ==> (result == lst2) // If lst2 has fewer chars, return lst2
    ensures (SumChars(lst1) == SumChars(lst2)) ==> (result == lst1) // If equal, return lst1

    var sum1 := SumChars(lst1);
    var sum2 := SumChars(lst2);

    if sum1 < sum2 {
        result := lst1;
    } else {
        result := lst2;
    }

    return result;

method SumChars(lst: seq<string>) returns (total: int)
    requires |lst| >= 0
    ensures total >= 0 // Total number of characters is non-negative
    ensures total == |lst| + SumLengths(lst) // Total is the sum of lengths of strings in the list

    var totalChars := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst| // i is within bounds
        invariant totalChars == SumLengths(lst[..i]) // Total chars counted so far
    {
        totalChars := totalChars + |lst[i]|;
        i := i + 1;
    }
    return totalChars;

function SumLengths(lst: seq<string>) : int
    ensures result >= 0 // Sum of lengths is non-negative
    ensures result == |lst| // If the list is empty, result is 0
{
    if |lst| == 0 {
        return 0;
    } else {
        return |lst[0]| + SumLengths(lst[1..]);
    }
}

